import re

def parse(lines):
    fields = []
    meta = {}
    mlines = []
    rows = []
    rlines = []
    skip = []
    for i, l in enumerate(lines):
        if not l.strip():
            continue
        if l.startswith('#'):
            m = re.match(r'#(\w+)[\t ]+(.*)$', l)
            if not m:
                skip.append(i)
                continue
            k, v = m.group(1), m.group(2)
            if k == 'fields':
                fields = v.split('\t')
                skip.append(i)
            elif k == 'types':
                skip.append(i)
            else:
                meta[k] = v
                mlines.append(i)
            continue
        parts = l.split('\t')
        if not fields:
            fields = ['field%d' % j for j in range(len(parts))]
        rec = {}
        for j, f in enumerate(fields):
            rec[f] = parts[j] if j < len(parts) else ''
        rows.append(rec)
        rlines.append(i)
    blocks = []
    if mlines:
        blocks.append({'name': 'log_metadata', 'kind': 'kv', 'lines': mlines, 'records': [meta]})
    if rlines:
        blocks.append({'name': 'connections', 'kind': 'table', 'lines': rlines, 'records': rows})
    return {'blocks': blocks, 'skip': skip}
